/**
 * The market's logo, as the printer wants it, at several sizes.
 *
 * A thermal head has no greys — every dot is ink or paper — so the artwork is
 * reduced to a one-bit raster here rather than at print time.
 *
 * SEVERAL SIZES, because this printer's ceiling for a single image is not
 * documented anywhere and finding it by trial cost a working evening. The
 * office picks a size and prints a test; whichever one the printer accepts is
 * the one that gets used. 384 dots is nearly the full 504-dot line; 128 is a
 * modest mark above the address.
 *
 * Generated from public/logo-receipt.png.
 */

export type LogoSize = 128 | 192 | 256 | 320 | 384;

export const LOGO_SIZES: LogoSize[] = [128, 192, 256, 320, 384];

export type LogoRaster = { width: number; height: number; data: string };

